{"command": "cd /workdir && python -c "
import json
d = json.load(open('output/analysis_results.json'))
assert set(d) == {'eda_results','hypothesis_test_results'}
assert set(d['eda_results']['sales_stats_by_region']) == {'Region A','Region B','Region C'}
assert isinstance(d['eda_results']['unique_product_count'], int)
h = d['hypothesis_test_results']
for k in ['hypothesis','assumption_checks','chosen_test','test_justification','t_statistic','u_statistic','p_value','confidence_interval_lower','confidence_interval_upper','conclusion']:
    assert k in h, k
print('Structure OK')
""}

